t.script:

const POLL_MS = 1500;

// ── Helpers ───────────────────────────────────────────
function esc(s) {
    return String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
}

function modalityLabel(m) {
    if (!m) return "—";
    const parts = [m.modality_type, m.identifier, m.ship_name].filter(Boolean);
    return parts.length ? parts.join(" / ") : "—";
}

// ── Modal ─────────────────────────────────────────────
function buildNomCard(nom, index, startOpen) {
    const refs = nom.references || {};
    const refStr = Object.entries(refs).map(([k,v]) => `${k}: ${v}`).join(", ") || `#${index+1}`;
    const meta = [nom.transporter, nom.receiver ? `→ ${nom.receiver}` : null, nom.arrival_date ? nom.arrival_date.split("T")[0] : null].filter(Boolean).join(" · ");

    const pts = (nom.product_transfers || []).map(pt => `
        <tr>
            <td>${esc(pt.product_name)}</td>
            <td>${esc(pt.amount)} ${esc(pt.unit_of_measurement)}</td>
            <td>${esc(pt.customs_type)}</td>
            <td>${esc(modalityLabel(pt.source_modality))}</td>
            <td>${esc(modalityLabel(pt.destination_modality))}</td>
        </tr>`).join("");

    const surveyFields = ["sample_required","inspection_before","inspection_after","certificate_of_analysis"];
    const surveyKvs = surveyFields.filter(f => nom.survey && nom.survey[f]).map(f =>
        `<span class="kv-key">${f.replace(/_/g," ")}</span><span class="kv-val">Yes</span>`
    ).join("");

    return `
        <div class="nom-card${startOpen ? " open" : ""}">
            <div class="nom-summary">
                <div class="nom-summary-left">
                    <span class="nom-ref">${esc(refStr)}</span>
                    <span class="nom-meta">${esc(meta)}</span>
                </div>
                <span class="nom-badge">${esc(nom.nomination_type || "—")}</span>
                <span class="nom-chevron">▶</span>
            </div>
            <div class="nom-detail">
                <div class="detail-section">
                    <div class="detail-section-title">Details</div>
                    <div class="kv-grid">
                        <span class="kv-key">Sender</span><span class="kv-val">${esc(nom.sender)}</span>
                        <span class="kv-key">Transporter</span><span class="kv-val">${esc(nom.transporter)}</span>
                        <span class="kv-key">Receiver</span><span class="kv-val">${esc(nom.receiver)}</span>
                        <span class="kv-key">Arrival</span><span class="kv-val">${esc((nom.arrival_date||"").split("T")[0])}</span>
                        ${nom.agent ? `<span class="kv-key">Agent</span><span class="kv-val">${esc(nom.agent)}</span>` : ""}
                    </div>
                </div>
                ${pts ? `
                <div class="detail-section">
                    <div class="detail-section-title">Product Transfers</div>
                    <table class="pt-table">
                        <thead><tr>
                            <th>Product</th><th>Amount</th><th>Customs</th><th>From</th><th>To</th>
                        </tr></thead>
                        <tbody>${pts}</tbody>
                    </table>
                </div>` : ""}
                ${surveyKvs ? `
                <div class="detail-section">
                    <div class="detail-section-title">Survey</div>
                    <div class="kv-grid">${surveyKvs}</div>
                </div>` : ""}
            </div>
        </div>`;
}

function openModal(json) {
    const data = (json.result || {}).data || {};
    const nominations = data.nominations || [];
    const subject = data.subject || json.id || "";
    const from = data.from || "";

    const nomHtml = nominations.map((n, i) =>
        buildNomCard(n, i, nominations.length === 1)
    ).join("");

    const backdrop = document.createElement("div");
    backdrop.className = "modal-backdrop";
    backdrop.innerHTML = `
        <div class="modal" role="dialog" aria-modal="true">
            <div class="modal-header">
                <div class="modal-header-text">
                    <h2>${esc(subject)}</h2>
                    <p>${esc(from)}</p>
                </div>
                <button class="modal-close" aria-label="Close">✕</button>
            </div>
            <div class="modal-body">${nomHtml}</div>
        </div>`;

    backdrop.querySelector(".modal-close").addEventListener("click", () => backdrop.remove());
    backdrop.addEventListener("click", e => { if (e.target === backdrop) backdrop.remove(); });
    backdrop.querySelectorAll(".nom-summary").forEach(el => {
        el.addEventListener("click", () => el.closest(".nom-card").classList.toggle("open"));
    });

    document.body.appendChild(backdrop);
}

// ── Job cards ─────────────────────────────────────────
function createCard(filename, container) {
    const card = document.createElement("div");
    card.className = "job-card";
    card.innerHTML = `
        <div class="job-header">
            <span class="job-filename" title="${filename}">${filename}</span>
            <span class="job-status status-uploading">Uploading</span>
        </div>
        <div class="job-progress">
            <span class="spinner"></span>
            <span class="job-progress-text">Sending file…</span>
        </div>`;
    (container || document.getElementById("jobs")).prepend(card);
    return {
        setStatus(label, cls) {
            const s = card.querySelector(".job-status");
            s.textContent = label;
            s.className = `job-status ${cls}`;
        },
        setProgress(text) {
            card.querySelector(".job-progress-text").textContent = text;
        },
        setJobId(id) {
            let el = card.querySelector(".job-id");
            if (!el) {
                el = document.createElement("div");
                el.className = "job-id";
                card.querySelector(".job-header").after(el);
            }
            el.textContent = `Job: ${id}`;
        },
        showResult(json) {
            card.querySelector(".job-progress").remove();
            // Invalidate list caches so next visit shows fresh data
            delete listCache.extractions;
            delete listCache.nominations;
            const btn = document.createElement("button");
            btn.className = "result-btn";
            btn.textContent = "View Result →";
            btn.addEventListener("click", () => openModal(json));
            card.appendChild(btn);
        },
        showError(msg) {
            this.setStatus("Error", "status-error");
            card.querySelector(".job-progress-text").textContent = msg;
            card.querySelector(".spinner").remove();
        }
    };
}

async function processFile(file) {
    const ui = createCard(file.name);
    try {
        const form = new FormData();
        form.append("msg_file", file);
        const submitResp = await fetch("/email_parser/submit", {
            method: "POST",
            body: form,
        });
        const submitData = await submitResp.json();
        if (submitData.error) throw new Error(submitData.error);

        const jobId = submitData.id;
        ui.setJobId(jobId);
        ui.setStatus("Pending", "status-pending");
        ui.setProgress("Waiting for result…");

        while (true) {
            await new Promise(r => setTimeout(r, POLL_MS));
            const pollResp = await fetch(`/email_parser/poll/${jobId}`);
            const result   = await pollResp.json();
            if (result.error) throw new Error(result.error);
            if (result.status !== "PENDING") {
                const ok = result.status_code >= 200 && result.status_code < 300;
                ui.setStatus(result.status, ok ? "status-success" : "status-error");
                ui.showResult(result);
                return;
            }
        }
    } catch (err) {
        ui.showError(err.message);
    }
}

// ── List views ────────────────────────────────────────
const listCache = {};

async function loadExtractions() {
    if (listCache.extractions) { renderExtractions(listCache.extractions); return; }
    const el = document.getElementById("extractions-content");
    el.innerHTML = '<div class="list-loading"><span class="spinner"></span> Loading…</div>';
    try {
        const resp = await fetch("/email_parser/api/extractions");
        const data = await resp.json();
        listCache.extractions = data;
        renderExtractions(data);
    } catch {
        el.innerHTML = '<p class="list-empty">Failed to load extractions.</p>';
    }
}

function renderExtractions(items) {
    const el = document.getElementById("extractions-content");
    if (!items.length) {
        el.innerHTML = '<p class="list-empty">No extractions yet.</p>';
        return;
    }
    el.innerHTML = items.map(e => `
        <div class="list-item" data-id="${e.id}">
            <div class="list-item-title">${esc(e.subject || e.job_id || "—")}</div>
            <div class="list-item-meta">${esc(e.email_from)} · ${e.nomination_count} nomination${e.nomination_count !== 1 ? "s" : ""}</div>
        </div>`).join("");
    el.querySelectorAll(".list-item").forEach(item => {
        item.addEventListener("click", async () => {
            const resp = await fetch(`/email_parser/api/extraction/${item.dataset.id}`);
            const json = await resp.json();
            openModal(json);
        });
    });
}

async function loadNominations() {
    if (listCache.nominations) { renderNominations(listCache.nominations); return; }
    const el = document.getElementById("nominations-content");
    el.innerHTML = '<div class="list-loading"><span class="spinner"></span> Loading…</div>';
    try {
        const resp = await fetch("/email_parser/api/nominations");
        const data = await resp.json();
        listCache.nominations = data;
        renderNominations(data);
    } catch {
        el.innerHTML = '<p class="list-empty">Failed to load nominations.</p>';
    }
}

function renderNominations(items) {
    const el = document.getElementById("nominations-content");
    if (!items.length) {
        el.innerHTML = '<p class="list-empty">No nominations yet.</p>';
        return;
    }
    el.innerHTML = items.map(n => {
        const refStr = Object.entries(n.references || {}).map(([k,v]) => `${v}`).join(", ") || "—";
        const meta = [n.nomination_type, n.transporter, n.arrival_date].filter(Boolean).join(" · ");
        return `<div class="list-item" data-id="${n.id}">
            <div class="list-item-title">${esc(refStr)}${n.subject ? ` — ${esc(n.subject)}` : ""}</div>
            <div class="list-item-meta">${esc(meta)}</div>
        </div>`;
    }).join("");
    el.querySelectorAll(".list-item").forEach(item => {
        item.addEventListener("click", async () => {
            const resp = await fetch(`/email_parser/api/nomination/${item.dataset.id}`);
            const json = await resp.json();
            openModal(json);
        });
    });
}

// ── Navigation ────────────────────────────────────────
document.querySelectorAll(".nav-item").forEach(navItem => {
    navItem.addEventListener("click", () => {
        const viewName = navItem.dataset.view;
        document.querySelectorAll(".nav-item").forEach(n => n.classList.remove("active"));
        navItem.classList.add("active");
        document.querySelectorAll(".view").forEach(v => v.classList.remove("active"));
        document.getElementById(`view-${viewName}`).classList.add("active");
        if (viewName === "extractions") loadExtractions();
        else if (viewName === "nominations") loadNominations();
    });
});

// ── Drop zone ─────────────────────────────────────────
const zone  = document.getElementById("drop-zone");
const input = document.getElementById("file-input");

zone.addEventListener("click", () => input.click());
input.addEventListener("change", () => {
    [...input.files].forEach(processFile);
    input.value = "";
});
zone.addEventListener("dragover", e => { e.preventDefault(); zone.classList.add("drag-over"); });
zone.addEventListener("dragleave", () => zone.classList.remove("drag-over"));
zone.addEventListener("drop", e => {
    e.preventDefault();
    zone.classList.remove("drag-over");
    const files = [...e.dataTransfer.files].filter(f => f.name.toLowerCase().endsWith(".msg"));
    if (files.length) files.forEach(processFile);
});

// ── Instruct view ─────────────────────────────────────
const instructDrop  = document.getElementById("instruct-drop");
const instructInput = document.getElementById("instruct-file-input");
const instructChips = document.getElementById("instruct-file-chips");
let instructFiles = [];

function renderChips() {
    instructChips.innerHTML = instructFiles.map((f, i) => `
        <span class="file-chip">${esc(f.name)}<button class="file-chip-remove" data-i="${i}">✕</button></span>
    `).join("");
    instructChips.querySelectorAll(".file-chip-remove").forEach(btn => {
        btn.addEventListener("click", () => {
            instructFiles.splice(Number(btn.dataset.i), 1);
            renderChips();
        });
    });
}

instructDrop.addEventListener("click", () => instructInput.click());
instructInput.addEventListener("change", () => {
    instructFiles.push(...instructInput.files);
    instructInput.value = "";
    renderChips();
});
instructDrop.addEventListener("dragover", e => { e.preventDefault(); instructDrop.classList.add("drag-over"); });
instructDrop.addEventListener("dragleave", () => instructDrop.classList.remove("drag-over"));
instructDrop.addEventListener("drop", e => {
    e.preventDefault();
    instructDrop.classList.remove("drag-over");
    instructFiles.push(...e.dataTransfer.files);
    renderChips();
});

document.getElementById("instruct-submit").addEventListener("click", async () => {
    const body = document.getElementById("instruct-body").value.trim();
    if (!body && instructFiles.length === 0) return;

    const form = new FormData();
    form.append("body_content", body);
    instructFiles.forEach(f => form.append("attachments", f));

    const ui = createCard("Instruction", document.getElementById("instruct-jobs"));
    try {
        const submitResp = await fetch("/email_parser/instruct", {
            method: "POST",
            body: form,
        });
        const submitData = await submitResp.json();
        if (submitData.error) throw new Error(submitData.error);

        const jobId = submitData.id;
        ui.setJobId(jobId);
        ui.setStatus("Pending", "status-pending");
        ui.setProgress("Waiting for result…");

        while (true) {
            await new Promise(r => setTimeout(r, POLL_MS));
            const pollResp = await fetch(`/email_parser/poll/${jobId}`);
            const result   = await pollResp.json();
            if (result.error) throw new Error(result.error);
            if (result.status !== "PENDING") {
                const ok = result.status_code >= 200 && result.status_code < 300;
                ui.setStatus(result.status, ok ? "status-success" : "status-error");
                ui.showResult(result);
                return;
            }
        }
    } catch (err) {
        ui.showError(err.message);
    }
});
